// ─── Catalogue d'exercices (unique, commun à tous les profils) ───────────────
// sports   → sports pour lesquels l'exercice est proposé (identifiants de Onboarding.js)
// f: true  → exercice mis en avant sur les profils « femme » (voir catalogFor)
// img      → dossier de photos dans free-exercise-db (domaine public, github.com/yuhonas/free-exercise-db)
//            Deux photos par exercice : 0.jpg (départ) et 1.jpg (arrivée). Chaque dossier n'est utilisé qu'une fois.
// pic      → une seule photo, pour les exercices absents de free-exercise-db (Wikimedia Commons, voir exercisePics.js)
// Les exercices sans img ni pic n'ont pas encore de photo : l'appli affiche un pictogramme à la place.
import { EX_PICS } from "./exercisePics";

const IMG_BASE = "https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/";

// Photos d'un exercice : [départ, arrivée], ou [photo unique], ou null s'il n'en a pas.
// Les séances enregistrées gardent une copie de l'exercice : on retrouve sa photo par son identifiant.
export const exPhotos = (ex) => {
  const img = ex?.img || EXERCISES.find((e) => e.id === ex?.id)?.img;
  if (img) return [0, 1].map((n) => IMG_BASE + img + "/" + n + ".jpg");
  return EX_PICS[ex?.id] ? [EX_PICS[ex.id]] : null;
};

