// Catalogue dans l'ordre d'affichage : sur un profil « femme », les exercices mis en avant passent en premier
export const catalogFor = (gender) =>
  gender === "femme" ? [...EXERCISES.filter((e) => e.f), ...EXERCISES.filter((e) => !e.f)] : EXERCISES;

export const CATEGORIES = [...new Set(EXERCISES.map((e) => e.cat))];

// Sports qui ont leur propre pastille dans le catalogue (musculation et cardio sont déjà couverts par les catégories)
export const SPORTS = [
  { id: "boxe", label: "Boxe" }, { id: "course", label: "Course" }, { id: "yoga", label: "Yoga" },
  { id: "danse", label: "Danse" }, { id: "velo", label: "Vélo" }, { id: "natation", label: "Natation" },
  { id: "crossfit", label: "CrossFit" }, { id: "sports-co", label: "Sports co" },
];

// Fiche complète d'un exercice : les séances n'en gardent parfois qu'une copie allégée
export const fullEx = (ex) => ({ ...ex, ...EXERCISES.find((e) => e.id === ex.id) });

// Recherche sans tenir compte des accents ni de la casse, sur le nom, les muscles et le matériel
const plain = (t) => t.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
export const exMatches = (ex, search) =>
  search === "" || plain([ex.name, ...(ex.muscles || []), ex.equip || ""].join(" ")).includes(plain(search));
